 void plan(){queue.removeAllViews();List<AgentCore.Step> steps=AgentCore.parse(command.getText().toString());if(steps.isEmpty()){showStatus("اكتب أمراً أولاً");return;}int i=0;for(AgentCore.Step s:steps){LinearLayout item=col();item.setPadding(d(10),d(10),d(10),d(10));item.setBackground(bg(CARD));add(item,text((++i)+". "+AgentCore.label(s.kind)+"\n"+s.arg,15,TEXT));add(item,btn("تنفيذ هذه الخطوة",()->run(s)));add(queue,item);}showStatus("راجع الخطة ثم نفّذ الخطوات واحدة تلو الأخرى.");}
 void launch(Intent i){try{startActivity(i);showStatus("تم فتح شاشة النظام");}catch(Exception e){showStatus("لا يوجد تطبيق مناسب لهذا الأمر");}}
 void search(String s){if(s.isEmpty()){showStatus("أدخل عبارة البحث");return;}launch(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.google.com/search?q="+Uri.encode(s))));}
 void openApp(String s){String n=AgentCore.norm(s);String pkg=null;if(n.equals("واتساب")||n.equals("whatsapp"))pkg="com.whatsapp";else if(n.equals("يوتيوب")||n.equals("youtube"))pkg="com.google.android.youtube";else if(n.equals("انستغرام")||n.equals("انستقرام")||n.equals("instagram"))pkg="com.instagram.android";else if(n.equals("فيسبوك")||n.equals("facebook"))pkg="com.facebook.katana";else if(n.equals("كروم")||n.equals("chrome"))pkg="com.android.chrome";else if(n.equals("تيك توك")||n.equals("tiktok"))pkg="com.zhiliaoapp.musically";else if(n.equals("الاعدادات")){launch(new Intent(Settings.ACTION_SETTINGS));return;}else if(n.equals("الكاميرا")){launch(new Intent(android.provider.MediaStore.INTENT_ACTION_STILL_IMAGE_CAMERA));return;}if(pkg!=null){Intent i=getPackageManager().getLaunchIntentForPackage(pkg);if(i!=null){launch(i);return;}}showStatus("التطبيق غير مثبت أو غير مدعوم. جرّب فتح رابط HTTPS.");}
 void run(AgentCore.Step s){switch(s.kind){case SEARCH:search(s.arg);break;case OPEN:try{URI u=new URI(s.arg);if(u.getHost()==null||!("https".equalsIgnoreCase(u.getScheme())||"http".equalsIgnoreCase(u.getScheme())))throw new Exception();launch(new Intent(Intent.ACTION_VIEW,Uri.parse(s.arg)));}catch(Exception e){showStatus("رابط غير صالح");}break;case APP:openApp(s.arg);break;case DIAL:if(AgentCore.validNumber(s.arg))launch(new Intent(Intent.ACTION_DIAL,Uri.fromParts("tel",s.arg,null)));else showStatus("اكتب رقم الهاتف فقط");break;case SMS:String[] p=s.arg.split("\\s+",2);if(!AgentCore.validNumber(p[0])){showStatus("الصيغة: رسالة 0790000000 النص");break;}launch(new Intent(Intent.ACTION_SENDTO,Uri.fromParts("smsto",p[0],null)).putExtra("sms_body",p.length==2?p[1]:""));break;case SETTINGS:launch(new Intent(Settings.ACTION_SETTINGS));break;case NOTE:String notes=prefs.getString("notes","");if(notes.length()+s.arg.length()>100000){showStatus("الملاحظات ممتلئة");break;}prefs.edit().putString("notes",notes+(notes.isEmpty()?"":"\n\n")+s.arg).apply();show("تم حفظ الملاحظة محلياً: "+s.arg);break;case DRAFT:show(AgentCore.draft(s.arg));break;case READ:try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/*"),FILE);}catch(Exception e){showStatus("تعذر فتح مدير الملفات");}break;case AI:ask(s.arg);break;default:show("الأوامر: ابحث عن ...\nافتح واتساب / يوتيوب / رابط HTTPS\nاتصل 079...\nرسالة 079... النص\nالإعدادات\nاحفظ ملاحظة ...\nاكتب إعلان / منشور / سيناريو ...\nبرومبت ...\nاقرأ ملف\nاسأل الذكاء ...\nكل سطر خطوة. لا يجري اتصال أو إرسال تلقائي.");}}
 void voice(){try{Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_LANGUAGE,"ar-JO").putExtra(RecognizerIntent.EXTRA_PROMPT,"تحدث بالعربية");startActivityForResult(i,VOICE);}catch(Exception e){showStatus("خدمة الإملاء غير متوفرة على الجهاز");}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null)return;if(req==VOICE){ArrayList<String> a=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(a!=null&&!a.isEmpty())command.setText(a.get(0));}else if(req==FILE&&data.getData()!=null){try(InputStream in=getContentResolver().openInputStream(data.getData())){if(in==null)throw new IOException();show(readLimited(in,100000));}catch(Exception e){showStatus("تعذر قراءة الملف النصي أو حجمه أكبر من 100KB");}}}
 static String readLimited(InputStream in,int max)throws IOException{ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){if(o.size()+n>max)throw new IOException("too large");o.write(buf,0,n);}return new String(o.toByteArray(),StandardCharsets.UTF_8);}
 static final String GOOGLE="generativelanguage.googleapis.com", GEMINI_URL="https://generativelanguage.googleapis.com/v1beta/models", GEMINI_MODEL="gemini-3.5-flash-lite", GROQ_URL="https://api.groq.com/openai/v1/chat/completions";
 static String host(String u){try{return new URI(u).getHost()==null?"":new URI(u).getHost().toLowerCase(Locale.ROOT);}catch(Exception e){return "";}}
 static String modelName(String m){return m.startsWith("models/")?m.substring(7):m;}
 void configure(){
  LinearLayout l=col(); l.setPadding(d(16),d(8),d(16),d(8)); l.setBackgroundColor(BG);
  String saved=prefs.getString("endpoint",""); String savedModel=prefs.getString("model","");
  EditText url=edit("رابط المحرك",saved.isEmpty()?GEMINI_URL:saved),model=edit("اسم النموذج",savedModel.isEmpty()?GEMINI_MODEL:savedModel),key=edit("مفتاح API (للجلسة فقط)",sessionKey);
  key.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);
  for(EditText field:new EditText[]{url,model,key}){field.setSingleLine(true);field.setTextDirection(View.TEXT_DIRECTION_LTR);field.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);}
  add(l,text("اختر Gemini أو Groq، ثم الصق مفتاح المزود. المفتاح لا يُحفظ بعد إغلاق العملية. لا تفعّل الفوترة إذا أردت الاستخدام المجاني.",14,TEXT));
  add(l,btn("Google Gemini — إعداد تلقائي",()->{if(!GOOGLE.equals(host(url.getText().toString().trim())))key.setText("");url.setText(GEMINI_URL);model.setText(GEMINI_MODEL);}));
  add(l,btn("Groq — إعداد تلقائي",()->{if(!"api.groq.com".equals(host(url.getText().toString().trim())))key.setText("");url.setText(GROQ_URL);model.setText("openai/gpt-oss-120b");}));
  add(l,url);add(l,model);add(l,key);
  ScrollView sc=new ScrollView(this);sc.addView(l);
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("إعداد محرك AI").setView(sc).setNegativeButton("إلغاء",null).setPositiveButton("حفظ واختبار",null).setNeutralButton("حفظ فقط",null).create();
  dialog.setOnShowListener(v->{Runnable save=()->{String u=url.getText().toString().trim(),m=modelName(model.getText().toString().trim()),k=key.getText().toString().trim();
    if(!validEndpoint(u)){url.setError("رابط HTTPS صالح مطلوب");return;}
    if(m.isEmpty()||(GOOGLE.equals(host(u))&&!m.matches("[A-Za-z0-9._-]+"))){model.setError("اسم النموذج غير صالح");return;}
    if((GOOGLE.equals(host(u))||"api.groq.com".equals(host(u)))&&k.isEmpty()){key.setError("ألصق مفتاح API الخاص بالمزود");return;}
    if(k.contains("\n")||k.contains("\r")||k.contains(" ")){key.setError("المفتاح يجب أن يكون دون مسافات");return;}
    if(GOOGLE.equals(host(u)))u=GEMINI_URL;
    if(!sessionKey.isEmpty()&&k.equals(sessionKey)&&!sessionHost.isEmpty()&&!sessionHost.equals(host(u))){key.setError("أدخل مفتاحاً خاصاً بالمزود الجديد");return;}
    prefs.edit().putString("endpoint",u).putString("model",m).apply();sessionKey=k;sessionHost=host(u);dialog.dismiss();showStatus("تم حفظ إعدادات المحرك");};
    dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(w->save.run());
    dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{save.run();if(!dialog.isShowing())ask("ما هي عاصمة الأردن؟ أجب بكلمة واحدة.");});
  });dialog.show();
 }
 static boolean validEndpoint(String s){try{URI u=new URI(s);String h=u.getHost();return h!=null&&u.getUserInfo()==null&&u.getFragment()==null&&u.getQuery()==null&&("https".equalsIgnoreCase(u.getScheme())||("http".equalsIgnoreCase(u.getScheme())&&(h.equalsIgnoreCase("localhost")||h.equals("127.0.0.1")||h.equals("[::1]"))));}catch(Exception e){return false;}}
 void ask(String prompt){
  String endpoint=prefs.getString("endpoint",""),model=modelName(prefs.getString("model","").trim()),provider=host(endpoint);
  boolean google=GOOGLE.equals(provider);
  if(!validEndpoint(endpoint)||model.isEmpty()){showStatus("اضغط إعداد محرك الذكاء الاصطناعي أولاً.");return;}
  if(google&&!model.matches("[A-Za-z0-9._-]+")){showStatus("اسم نموذج Gemini غير صالح.");return;}
  if((google||"api.groq.com".equals(provider))&&sessionKey.isEmpty()){showStatus("مفتاح API غير موجود في الجلسة. افتح الإعدادات والصقه ثم احفظ واختبر.");return;}
  if(!sessionKey.isEmpty()&&!provider.equals(sessionHost)){showStatus("المفتاح لا يطابق المزود الحالي. أعد إعداد المحرك.");return;}
  if(busy){showStatus("يوجد طلب جارٍ");return;}if(prompt.length()>20000){showStatus("النص طويل جداً");return;}
  final String address=google?GEMINI_URL+"/"+model+":generateContent":endpoint;
  new AlertDialog.Builder(this).setTitle("إرسال إلى محرك AI؟").setMessage("سيُرسل نص الأمر إلى: "+provider+". قد يفرض المزود رسوماً خارج الحصة المجانية. لا ترسل معلومات خاصة. المحرك لا يتحكم بالتطبيقات تلقائياً.").setNegativeButton("إلغاء",null).setPositiveButton("إرسال",(a,b)->{
   if(busy)return;busy=true;showStatus("جاري طلب الرد من "+provider+"...");final String key=sessionKey;
   new Thread(()->{HttpURLConnection c=null;try{
    c=(HttpURLConnection)new URL(address).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(20000);c.setReadTimeout(90000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=UTF-8");c.setRequestProperty("Accept","application/json");
    String system="أنت مساعد عربي. أجب عن الأسئلة واكتب مسودات وخططاً نصية فقط. لا تدع أنك نفذت إجراءات خارجية أو قرأت تطبيقات أخرى.";
    JSONObject request;
    if(google){c.setRequestProperty("x-goog-api-key",key);request=new JSONObject().put("systemInstruction",new JSONObject().put("parts",new JSONArray().put(new JSONObject().put("text",system)))).put("contents",new JSONArray().put(new JSONObject().put("role","user").put("parts",new JSONArray().put(new JSONObject().put("text",prompt)))));}
    else{if(!key.isEmpty())c.setRequestProperty("Authorization","Bearer "+key);request=new JSONObject().put("model",model).put("messages",new JSONArray().put(new JSONObject().put("role","system").put("content",system)).put(new JSONObject().put("role","user").put("content",prompt)));}
    byte[] body=request.toString().getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(body.length);try(OutputStream o=c.getOutputStream()){o.write(body);}
    int code=c.getResponseCode();if(code<200||code>=300){String raw="";try(InputStream in=c.getErrorStream()){if(in!=null)raw=readLimited(in,65536);}catch(Exception ignored){} final String problem=httpProblem(code)+safeReason(raw);runOnUiThread(()->showStatus(problem));return;}
    JSONObject response;try(InputStream in=c.getInputStream()){response=new JSONObject(readLimited(in,1000000));}
    String answer=extractAnswer(response,google);
    if(answer.trim().isEmpty()){runOnUiThread(()->showStatus("HTTP "+code+": وصل الرد دون نص قابل للعرض. تحقق من النموذج أو جرّب سؤالاً آخر."));}
    else runOnUiThread(()->{show(answer);showStatus("نجح الاتصال — HTTP "+code+" · "+model);});
   }catch(Exception e){final String problem=connectionProblem(e);runOnUiThread(()->showStatus(problem));}finally{if(c!=null)c.disconnect();runOnUiThread(()->busy=false);}}).start();
  }).show();
 }
 static String extractAnswer(JSONObject response,boolean google){
  if(google){JSONArray candidates=response.optJSONArray("candidates");if(candidates==null||candidates.length()==0)return "";JSONObject candidate=candidates.optJSONObject(0);if(candidate==null)return "";JSONObject content=candidate.optJSONObject("content");if(content==null)return "";JSONArray parts=content.optJSONArray("parts");if(parts==null)return "";StringBuilder out=new StringBuilder();for(int i=0;i<parts.length();i++){JSONObject p=parts.optJSONObject(i);if(p!=null&&!p.optBoolean("thought",false)){String t=p.optString("text","");if(!t.isEmpty()){if(out.length()>0)out.append('\n');out.append(t);}}}return out.toString();}
  JSONArray choices=response.optJSONArray("choices");if(choices==null||choices.length()==0)return "";JSONObject choice=choices.optJSONObject(0);if(choice==null)return "";JSONObject msg=choice.optJSONObject("message");return msg==null||msg.isNull("content")?"":msg.optString("content","");
 }
 static String safeReason(String raw){ // Only fixed known codes; never display raw API errors or keys.
  String[] reasons={"API_KEY_INVALID","API_KEY_SERVICE_BLOCKED","API_KEY_HTTP_REFERRER_BLOCKED","ACCESS_TOKEN_TYPE_UNSUPPORTED","PERMISSION_DENIED","RESOURCE_EXHAUSTED","UNAUTHENTICATED","INVALID_ARGUMENT","FAILED_PRECONDITION","NOT_FOUND","UNAVAILABLE","model_not_found","invalid_api_key","rate_limit_exceeded"};
  for(String r:reasons)if(raw.contains("\""+r+"\""))return "\nرمز المزود: "+r;return "";
 }
 static String httpProblem(int code){switch(code){case 400:return "HTTP 400: طلب غير مقبول أو مفتاح غير صالح. تحقق من المفتاح والنموذج.";case 401:return "HTTP 401: مفتاح API مفقود أو غير صالح.";case 403:return "HTTP 403: الوصول مرفوض. تحقق من صلاحيات الحساب والمفتاح.";case 404:return "HTTP 404: النموذج أو الرابط غير موجود.";case 429:return "HTTP 429: تجاوز حدود الاستخدام أو الحصة المجانية.";case 500:case 502:case 503:case 504:return "HTTP "+code+": الخدمة غير متاحة مؤقتاً.";default:return "HTTP "+code+": رفض المحرك الطلب.";}}
 static String connectionProblem(Exception e){if(e instanceof java.net.UnknownHostException)return "Network / DNS: تعذر العثور على الخادم. تحقق من الإنترنت والعنوان.";if(e instanceof java.net.SocketTimeoutException)return "Network / Timeout: انتهت مهلة الاتصال أو الرد.";if(e instanceof javax.net.ssl.SSLException)return "Network / TLS: تعذر الاتصال الآمن بالخادم.";if(e instanceof java.net.ConnectException)return "Network: تعذر فتح الاتصال بالخادم.";if(e instanceof org.json.JSONException)return "JSON: صيغة رد المحرك غير متوقعة.";if(e instanceof java.io.IOException)return "Network / IO: تعذر إرسال الطلب أو قراءة الرد.";return "تعذر تنفيذ الطلب داخل التطبيق: "+e.getClass().getSimpleName();}
 @Override protected void onDestroy(){if(tts!=null){tts.stop();tts.shutdown();}super.onDestroy();}
